(function(){const e=document.createElement("link").relList;if(e&&e.supports&&e.supports("modulepreload"))return;for(const i of document.querySelectorAll('link[rel="modulepreload"]'))n(i);new MutationObserver(i=>{for(const a of i)if(a.type==="childList")for(const r of a.addedNodes)r.tagName==="LINK"&&r.rel==="modulepreload"&&n(r)}).observe(document,{childList:!0,subtree:!0});function t(i){const a={};return i.integrity&&(a.integrity=i.integrity),i.referrerPolicy&&(a.referrerPolicy=i.referrerPolicy),i.crossOrigin==="use-credentials"?a.credentials="include":i.crossOrigin==="anonymous"?a.credentials="omit":a.credentials="same-origin",a}function n(i){if(i.ep)return;i.ep=!0;const a=t(i);fetch(i.href,a)}})();const qn={eyebrow:"交互式硬件档案 · 001",title:["一束光，如何","成为一段","可读信号"],lead:"三层板叠在一起，才构成一次完整测量：激光头出光与收光，顶板把微弱信号放大并数字化，底板负责时序、供电与传输。",hint:"拖动旋转 · 滚轮缩放 · 点击板层或区域",chain:[{n:"02",title:"激光头",note:"出光 / 收光"},{n:"03",title:"顶板",note:"放大 · 滤波 · 数字化"},{n:"01",title:"底板",note:"调度 · 供电 · 传输"}],readme:[{k:"这是什么",v:"一台三层堆叠的激光传感硬件。三层板各自负责光学、模拟与数字，中间用 2.54mm 排针和 IPEX 同轴线连接。三块板都是双面板，元件分布在正反两面。"},{k:"怎么看",v:"先点左侧板层（或直接点模型上的板），再点板面上的发光标记。点中的区域如果在板的背面，板子会自动翻过来；也可以按「翻到背面」自己翻。拖动可以从下方观察。"}]},bn={laser:{index:"02",name:"激光头",subtitle:"发光、收光与光电转换",lead:"激光头是唯一接触被测表面的部分：一束光从这里出去，回光也从这里回来，并在同一块小板上完成光电转换。",note:"14 × 14 mm · 单板 1.6 mm"},top:{index:"03",name:"顶板",subtitle:"微弱信号调理与高精度采集",lead:"顶板处理的是最容易丢失的那一段：把光电流放大、滤掉高频毛刺，再交给 ADS8688 变成可以计算的数字。",note:"50 × 50 mm · 单板 1.6 mm"},bottom:{index:"01",name:"底板",subtitle:"系统控制、供电、存储与通信",lead:"底板是整机的指挥部：它决定什么时候发光、什么时候采样，也负责把电能和数据送到该去的地方。",note:"50 × 50 mm · 单板 1.6 mm"}},ga={"laser-z0":{title:"激光二极管与光机结构",tag:"光学起点",purpose:"发光和收光都发生在这里。TO-56 金属壳把激光二极管固定住，并给出一个稳定的光轴；回光沿同一条光路进入探测器。",why:"光路一旦偏移、松动，或者漏进环境光，接收到的能量就会变——而这个变化和被测对象毫无关系，会直接变成测量漂移。",how:"TO-56 是带窗口的金属封装：管座提供机械基准和散热，管帽上的窗口让光按设计方向进出，外壳同时充当遮光罩，把环境光挡在光路之外。半导体结在正向偏置下产生受激发射，出光强度基本由驱动电流决定，所以它需要的是恒流而不是恒压。",impact:"把「光路稳定」从偶然条件变成可复现的工程条件，后级放大才有稳定的输入。",flow:"恒流驱动 → <b>激光二极管</b> → 出光 → 被测面 → 回光 → 探测器"},"laser-z1":{title:"驱动与阻抗匹配",tag:"光电转换接口",purpose:"激光头自带的一小片电路：把输入的驱动电流调整到二极管需要的工作点，并把回光信号整根同轴送到顶板。",why:"激光头离主驱动电路有一段距离，线缆的寄生电感会改变驱动波形；把匹配放在光头附近，这段不确定性就被关在最小的范围里。",how:"DFN 封装的小芯片与周围阻容构成偏置与匹配网络；两枚 IPEX 座把驱动与回光分别用同轴线送出去，射频与模拟各自走自己的通路，避免形成地环路。",impact:"让光头与主板之间变成一段确定、可以整根更换的同轴通路，而不是一堆飞线。",flow:"顶板 → 同轴线 → <b>IPEX</b> → 匹配网络 → 激光二极管"},"top-z3":{title:"高精度采集",tag:"信号的数字化",purpose:"把调理好的模拟波形转换成主控能够计算、存储和回放的数字采样点——用的是 ADS8688，一颗 8 通道 16 位 ADC。",why:"光电信号里真正有用的变化很细微。量化精度不够，波形的幅度、上升沿和细节会被台阶化；后面的算法再聪明，也无法把丢掉的信息恢复出来。",how:"ADS8688 内部带 8 路模拟开关和 16 位 SAR 转换，按 SCLK 时钟逐位输出结果，CS# 选通、RST# 复位，都与底板 SPI 直连；片外 REF3040 提供 4.096V 基准，把「1 个数字码等于多少伏」钉死；REFSEL# 一路留给基准选择与旁路去耦。两枚 SOT-23 小芯片负责输入保护与偏置。",impact:"得到时间间隔明确、幅值可比较的数字波形，交给底板缓存、分析与传输。",flow:"调理后的电压 → <b>ADS8688 采样/量化</b> → SCLK/MISO 数字总线 → 底板"},"top-z2":{title:"光电前端与跨阻放大",tag:"一进一出",purpose:"回光在这里从「很小的一股电流」变成「可以测量的电压」，并在进 ADC 之前把不需要的高频成分滤掉。",why:"光电二极管的输出是电流，而且非常微弱；直接送进 ADC 会淹没在噪声里。电流还必须先在最短路径上转换成电压，否则走线本身的寄生参数就会把信号吃掉。",how:"IPEX 座把回光经同轴线引进来，OPA2320 双运放搭成跨阻放大级——反馈电阻决定增益、反馈电容决定带宽，两者一起决定「放大多少」和「多快」的折中；后级再做低通压掉高频毛刺。运放用 ±2.5V 双电源，输出才不会被压在零点附近削顶。",impact:"给整机一个干净的模拟入口：后面的 ADC 看到的是一个幅度合适、噪声受控的电压。",flow:"回光 → 光电流 → <b>跨阻放大</b> → 低通 → ADS8688"},"top-z0":{title:"激光恒流驱动与输出",tag:"照明基线",purpose:"给激光二极管提供受控、稳定的工作电流，并通过同轴线送到激光头。",why:"如果光源自己忽明忽暗，接收端会把光源的波动误认为被测对象的变化；过流还会缩短激光器寿命。恒流而不是恒压，才能让出光强度不随器件温漂漂走。",how:"LT3092 是一颗两端可编程电流源：外接一个电阻就设定输出电流，内部环路持续比较并修正，让电流不随输入电压和温度变化；Q3/Q4 组成 LD_EN 使能开关，磁珠把驱动电源单独滤一遍，再经 IPEX 送出。这一区同时有 2.54mm 排针，把电源与控制信号从底板接上来。",impact:"给整机一条稳定的「照明基线」——这条基线不稳，后面做得再精密也没有意义。",flow:"底板 +5V → <b>LT3092 恒流</b> → LD_EN 开关 → IPEX → 激光头"},"top-z1":{title:"负压生成与板间连接",tag:"双极性供电",purpose:"为模拟前端提供一路负电源，同时把底板送上来的电源、地和 SPI 信号接进顶板。",why:"运放要处理双向摆动的微弱信号，只有正电源时输出会在接近零点处被削平，波形的下半部分直接丢失。",how:"TPS63710 是反相升降压：把 +5V 变成 −3.3V，配合 2.2µH 电感和多颗 22µF 电容完成储能与滤波；TPS7A3901 再把正负两路稳成 ±2.5V。2.54mm 排针负责把电源与 SPI（SCLK/MOSI/MISO/CS#）从底板接上来，三颗电感分别串在各路电源出口，把开关噪声挡在模拟区之外。",impact:"让前级运放有完整的输出摆幅，也让顶板与底板之间只有一组确定的连接点。",flow:"底板 +5V/3V3D → <b>TPS63710 −3.3V</b> → TPS7A39 ±2.5V → 前端运放"},"bottom-z0":{title:"电源输入与充电管理",tag:"能量入口",purpose:"USB-C 接入的 5V 和电池电压，从这里进入整机，并在充放电之间做切换。",why:"电池电压会随电量从 4.2V 一路掉到 3.4V，而激光驱动、模拟前端和数字电路需要的电压各不相同。未经处理的电源直接分给三层，电压波动最后会被写进测量结果。",how:"USB-C 座进来先经过 PTC 自恢复保险丝（BSMD0603L-200）限流，CC 上两个 5.1k 电阻声明设备身份，D+/D− 串 22Ω 抑制边沿振铃；TP4056 负责单节锂电的恒流/恒压充电，1.2k 的 PROG 电阻设定充电电流，CHRG/STDBY 引脚直接点亮状态灯；TPS61088 再把电池升到稳定 5V，TPS62162 降到 3V3D。",impact:"让满电和低电时表现一致，并给模拟前端留出干净的电源环境。",flow:"USB-C / 电池 → <b>PTC + TP4056 充电</b> → TPS61088 升压 → 3V3D / 5V 各轨"},"bottom-z1":{title:"柔性排线座与板间互联",tag:"整机出口",purpose:"这里是整机对外的电气出口：几枚 1.25mm 间距的 FPC 座和 2.54mm 排针，把显示屏、按键、电池与扬声器接到主板上。",why:"板与板、板与外部件之间如果靠飞线，装配一致性差，弯折几次就可能接触不良。用排线座和排针，把「连接」变成可以插拔、可以复现的零件。",how:"7P 1.25mm FPC 座压住柔性排线的金手指，走 LCD 的 SPI（SCL/SDA/DC/RES/BLK）；4P 与 2P 座分别接外接模块与供电；2.54mm 排针把电源、地与 SPI/控制信号送到顶板和激光头。",impact:"让生产测试、固件维护和整机装配都有确定的接口，三层结构也因此可以拆开检修。",flow:"外部排线 ↔ <b>FPC 座</b> ↔ 排针 ↔ 顶板 / 激光头"},"bottom-z2":{title:"主控与存储",tag:"调度中心",purpose:"整台设备的调度中心：安排何时发光、何时采样，把数字波形缓存下来，再通过 USB 或无线送出去。",why:"激光头、模拟前端和 ADC 各自只完成一个环节。必须有统一的时序，把「发光—采样—传输」串成一次完整测量，否则三层板只是三个互不相干的模块。",how:"ESP32-S3R8 是一颗带 8MB PSRAM 的双核 MCU：SPI 主机读 ADS8688，GPIO 控制 LD_EN / AFE_EN，USB 直连 D+/D−；外挂的 W25Q128（16MB QSPI Flash）保存固件与波形；40MHz 晶振提供时间基准；去耦电容铺满芯片四周，让每次开关动作不把噪声带上电源。",impact:"把分散的硬件动作变成可重复的产品流程，并把原始采样组织成上层应用能用的数据。",flow:"ADC 数据 → <b>ESP32-S3 缓冲/处理</b> → Flash · USB · 无线"},"bottom-z3":{title:"按键与天线接口",tag:"现场操作",purpose:"两颗贴片按键负责复位与进入烧录模式；IPEX 座把 2.4GHz 射频能量送到天线。",why:"量产与维护都需要一个不拆机就能复位、能烧录的入口；射频路径则要求阻抗连续，否则能量会反射回来，传输距离和连接稳定性一起下降。",how:"RST 与 BOOT 直接拉低 ESP32 的 CHIP_PU 与启动引脚，配合两个 10k 上拉保证上电时序；射频侧用 2.4nH 电感加 1.5pF 电容做匹配，磁珠把数字电源挡在天线之外，再经 IPEX 座引出，外接天线。",impact:"让设备可以现场恢复、现场升级，并在没有线缆的情况下把测量结果送出去。",flow:"按键 → CHIP_PU / BOOT ｜ 射频 → <b>匹配网络</b> → IPEX → 天线"}},Eh=[["01","旋转模型","按住拖动可以从任意方向观察元件、焊盘、排线与同轴接头，也可以绕到模型下方。"],["02","选择板层","点击左侧列表或直接点模型上的板，进入单板聚焦。"],["03","点开区域","点击板面上的发光标记，右侧会展开这块区域在信号链里的作用。"],["04","翻看背面","区域在背面时板子会自动翻过来；也可以手动按「翻到背面」。"],["05","回到全景","点击空白处或按 Esc，逐级退回单板与三层全景。"],["06","编辑模式","按 E 打开编辑面板：可以改文字、挪板层高度、调整区域标记，并保存成初始样子。"]]